const contenido = ($json.message && $json.message.content) || {};

function limpiar(texto) {
  return texto
    ?.toString()
    .replace(/["]/g, '')
    .replace(/\n/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

const m1 = limpiar(contenido.mensaje_parte_1);
const m2 = limpiar(contenido.mensaje_parte_2);
const m3 = limpiar(contenido.mensaje_parte_3);
const m4 = limpiar(contenido.mensaje_parte_4);

let cantidad = parseInt(contenido.cantidad_de_mensajes || "0", 10);
const partes = [m1, m2, m3, m4].filter(p => p && p.length > 0);

// Normalizar cantidad a 1..4 para que Switch1 SIEMPRE case (nunca silencio)
if (!Number.isInteger(cantidad) || cantidad < 1 || cantidad > 4) {
  cantidad = partes.length >= 1 ? Math.min(partes.length, 4) : 1;
}

// Garantizar que el primer mensaje nunca esté vacío
let msg1 = m1;
if (!msg1) {
  try { msg1 = limpiar($('AI Agent').first().json.output); } catch (e) {}
  cantidad = 1;
}
if (!msg1) {
  msg1 = 'Perdona, no te he entendido bien. ¿Me lo repites?';
  cantidad = 1;
}

return [
  {
    json: {
      mensaje_1: msg1,
      mensaje_2: m2,
      mensaje_3: m3,
      mensaje_4: m4,
      tipo_respuesta: limpiar(contenido.tipo_respuesta),
      cantidad_de_mensajes: cantidad
    }
  }
];

// Acceder al primer item de entrada
const inputData = $input.all();

// Función para verificar el estado de la IA
function verificarEstadoIA(item) {
  try {
    const data = item.json;

    let lead;
    if (Array.isArray(data)) {
      lead = data[0]?._embedded?.leads?.[0];
    } else if (data._embedded?.leads) {
      lead = data._embedded.leads[0];
    } else if (data._embedded?.contacts) {
      // Input viene de Obtener contacto — buscar lead en nodo anterior
      lead = null;
    } else {
      lead = data;
    }

    // Intentar obtener lead desde el nodo Get list of leads
    if (!lead) {
      try {
        const leadsData = $('Get list of leads').first().json;
        if (leadsData._embedded?.leads) {
          lead = leadsData._embedded.leads[0];
        }
      } catch(e) {}
    }

    // Extraer teléfono del contacto (Obtener contacto - endpoint listado)
    let telefono = null;
    try {
      let contactData = $input.first().json;
      // n8n puede devolver el body como string en campo 'data'
      if (typeof contactData.data === 'string') {
        contactData = JSON.parse(contactData.data);
      }
      const contact = contactData._embedded?.contacts?.[0] || contactData;
      const phoneField = (contact.custom_fields_values || []).find(
        f => f.field_code === 'PHONE'
      );
      if (phoneField?.values?.[0]?.value) {
        telefono = phoneField.values[0].value;
      }
    } catch(e) {}

    // Extraer nombre del contacto (del webhook)
    let nombre_contacto = null;
    try {
      nombre_contacto = $('Edit Fields').first().json.nombre_contacto || null;
    } catch(e) {}

    if (!lead) {
      return {
        ia_apagada: false,
        campo_existe: false,
        lead_id: null,
        telefono,
        nombre_contacto,
        error: "No se encontró el lead"
      };
    }

    const customFields = lead.custom_fields_values || [];
    const campoApagarIA = customFields.find(
      field => field.field_name === "Apagar IA?"
    );

    if (campoApagarIA) {
      const valor = campoApagarIA.values?.[0]?.value;
      return {
        ia_apagada: valor === true,
        campo_existe: true,
        lead_id: lead.id,
        lead_name: lead.name,
        lead_completo: lead,
        telefono,
        nombre_contacto
      };
    }

    return {
      ia_apagada: false,
      campo_existe: false,
      lead_id: lead.id,
      lead_name: lead.name,
      lead_completo: lead,
      telefono,
      nombre_contacto
    };

  } catch (error) {
    return {
      ia_apagada: false,
      campo_existe: false,
      telefono: null,
      nombre_contacto: null,
      error: error.message
    };
  }
}

return inputData.map(item => {
  const resultado = verificarEstadoIA(item);
  return { json: resultado };
});

